def targetLinearPolynomial (n : ℕ) (ℓ : (ℂ × ℂ) →ₗ[ℂ] ℂ) : Polynomial n :=
  MvPolynomial.C (ℓ (1, 0)) * MvPolynomial.X (Sum.inr false) +
